def transform(g):
    h,w=len(g),len(g[0])
    dv=max(set(x for r in g for x in r), key=lambda c: sum(r.count(c) for r in g))  # divider color
    # divider rows/cols
    drows=[i for i in range(h) if all(g[i][j]==dv for j in range(w))]
    dcols=[j for j in range(w) if all(g[i][j]==dv for i in range(h))]
    # bands
    def segs(ds,n): 
        s=[];prev=-1
        for d in ds+[n]: s.append((prev+1,d)); prev=d
        return s
    bands=segs(drows,h); cells=segs(dcols,w)
    # find template shape: non-dv cells not in leftmost cell forming 2x2 square
    # gather components of non-dv cells
    from collections import deque
    seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=dv and not seen[i][j]:
                q=deque([(i,j)]);seen[i][j]=True;comp=[]
                while q:
                    y,x=q.popleft();comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny][nx] and g[ny][nx]!=dv:
                            seen[ny][nx]=True;q.append((ny,nx))
                comps.append(comp)
    square=lambda c: len(c)==4 and max(y for y,x in c)-min(y for y,x in c)==1 and max(x for y,x in c)-min(x for y,x in c)==1
    shape=[c for c in comps if not square(c)][0]
    # shape's band/cell
    ys=[y for y,x in shape]; xs=[x for y,x in shape]
    band=[b for b in bands if min(ys)>=b[0] and max(ys)<b[1]][0]
    cell=[c for c in cells if min(xs)>=c[0] and max(xs)<c[1]][0]
    template=[[(y,x) for y,x in shape] for _ in [0]][0]
    rel=[(y-min(ys),x-min(xs)) for y,x in shape]
    ph=max(y for y,x in rel)+1; pw=max(x for y,x in rel)+1
    # square color per band
    colors={}
    for c in comps:
        if square(c):
            b=[b for b in bands if c[0][0]>=b[0] and c[0][0]<b[1]][0]
            colors[b[0]]=g[c[0][0]][c[0][1]]
    out=[[dv]*w for _ in range(h)]
    for b in bands:
        col=colors.get(b[0])
        if col is None: continue
        for cl in cells:
            for y in range(b[0],b[1]):
                for x in range(cl[0],cl[1]):
                    ry=y-b[0]; rx=x-cl[0]
                    if ry<ph and rx<pw and (ry,rx) in rel:
                        out[y][x]=col
    return out

